    bool OnActionMessage(CActionMessage& Message);
    void OnAuthenticateMessage(const CAuthenticateMessage& Message);
    void AbortSASL(const CString& sFullIRCLine);
    bool IsDuringSASL() const { return !m_sSASLMechanism.empty(); }

