VCString params; params.push_back(CString(FUZZ_PARAM_STR())); params.push_back(CString(FUZZ_PARAM_STR()));
num->SetParams(std::move(params));
// Validation: Heap-allocated with numeric command and some parameters.

// Create or fetch the CZNC singleton instance. Guard to avoid double-initialization.
if (FUZZ_GET_ATTR_INT_GLOBAL("cznc_created") == 0) {
    CZNC::CreateInstance();
    FUZZ_SET_ATTR_INT_GLOBAL("cznc_created", 1);
}
CZNC* znc = &CZNC::Get();
// Optionally set some conservative defaults to keep environment benign
znc->SetMaxBufferSize((*FUZZ_PARAM(unsigned int)) % 256);
znc->SetConfigWriteDelay((*FUZZ_PARAM(unsigned int)) % 10);
// Validation: Returns a valid singleton pointer; lifetime managed by process.

// Construct an INVITE message with invited nick and channel.
