CString domain = ((*FUZZ_PARAM(unsigned int)) % 2) ? CString("znc") : (CString("znc-") + CString(FUZZ_PARAM_STR()).Left(16));
CString ctx = CString(FUZZ_PARAM_STR()).Left(16);
CString eng = CString(FUZZ_PARAM_STR()).Left(64);
CDelayedTranslation* dtrans = new CDelayedTranslation(domain, ctx, eng);
// Validation: Token constructed; resolution happens in downstream stubs.

