qmsg->SetCommand(CString("QUIT"));
qmsg->SetReason(CString(FUZZ_PARAM_STR()));
// Validation: Proper command and text parameter set.

// Plain metadata holder; default construction is sufficient.
CModInfo* minfo = new CModInfo();
// Optionally set a name/path for increased coverage
minfo->SetName(CString(FUZZ_PARAM_STR()));
minfo->SetPath(CString(FUZZ_PARAM_STR()));
// Validation: Heap-allocated and minimally initialized.

// Use concrete CClientAuth to satisfy abstract CAuthBase.
CClient* client = new CClient();
CString user(FUZZ_PARAM_STR());
