CAuthBase* auth = new CClientAuth(client, user, pass);
// Track ownership so a downstream cleanup stub could free client if needed
FUZZ_SET_ATTR_PTR(auth, "client_ptr", client);
// Validation: Returns a concrete auth object; associated client is kept alive.

