CNickMessage* nmsg = new CNickMessage();
// Set command to NICK to match message type
nmsg->SetCommand(CString("NICK"));

// Old nick (from prefix): build a CNick and attach
{
    std::string oldn = FUZZ_PARAM_STR();
    CString oldNick = CString(oldn.substr(0, 32));
    if (oldNick.empty()) oldNick = "old";
    CNick prefix(oldNick);
