// Enforce valid interval (seconds) and reasonable cycles to avoid heavy loops
unsigned int interval = (*FUZZ_PARAM(unsigned int) % 5) + 1;        // [1..5]
unsigned int cycles   = (*FUZZ_PARAM(unsigned int) % 10);           // [0..9], 0 = infinite

// Label and description; keep small and ensure non-empty label
