CString label = CString(rawLabel.substr(0, 32));
if (label.empty()) label = "timer";
std::string rawDesc = FUZZ_PARAM_STR();
CString desc = CString(rawDesc.substr(0, 128));

// Allocate timer and wire to module
CTimer* timer = new CTimer(module, interval, cycles, label, desc);
// Be explicit about association and potentially mutate description
timer->SetModule(module);
timer->SetDescription(desc);

// Track ownership metadata for safe downstream use (e.g., RemTimer/UnlinkTimer)
FUZZ_SET_ATTR_PTR(timer, "owner_module", module);
FUZZ_SET_ATTR_INT(timer, "interval", (int)interval);
FUZZ_SET_ATTR_INT(timer, "cycles", (int)cycles);
FUZZ_SET_ATTR_STR(timer, "label", label.c_str());

// Output both the module (still valid and not consumed) and the constructed timer
// Validation: Timer constructed with valid params and associated with the input module; no registration performed here.

// Construct a COptionalTranslation instance (either literal or delayed)
// Define and initialize the required output variable
COptionalTranslation* otrans = nullptr;

// Choose construction path using fuzzed branch value
unsigned int branch = *FUZZ_PARAM(unsigned int);

if ((branch & 1u) == 0u) {
    // Literal constructor path
    std::string txt = FUZZ_PARAM_STR();
    // Constrain size for performance and avoid overly large allocations
    CString literal(txt.substr(0, 512));
    otrans = new COptionalTranslation(literal);
} else {
    // Delayed translation constructor path
    // Use a plausible domain from a small list
    const char* domains[] = {"znc", "znc-core", "znc-mod", "znc-web"};
    const size_t domains_count = sizeof(domains) / sizeof(domains[0]);
    const CString dom(domains[branch % domains_count]);

    std::string ctxs = FUZZ_PARAM_STR();
    std::string engl = FUZZ_PARAM_STR();
    CString ctx(ctxs.substr(0, 64));
    CString eng(engl.substr(0, 256));

    CDelayedTranslation dt(dom, ctx, eng);
    otrans = new COptionalTranslation(dt);
}

// Property: output must be non-null so that the fuzzer can pool it
FUZZ_ASSERT(otrans != nullptr, "COptionalTranslation allocation failed");

// Validation summary: otrans is guaranteed non-null; string sizes bounded.

// Construct a CLanguageScope which pushes a language on creation
// Define and initialize the required output variable
CLanguageScope* lang_scope = nullptr;

// Pick a plausible language code from a small set
const char* langs[] = {"en", "de", "fr", "es", "ru", "zh", "it", "pt", "ja"};
unsigned int idx = *FUZZ_PARAM(unsigned int) % (sizeof(langs) / sizeof(langs[0]));

lang_scope = new CLanguageScope(CString(langs[idx]));

// Property: output must be non-null; destructor will pop language automatically
FUZZ_ASSERT(lang_scope != nullptr, "CLanguageScope allocation failed");

// Validation summary: lang_scope is guaranteed non-null and will manage language stack via RAII.

