import random
import string
from typing import List

# This generator produces seeded, valid hostname/hostmask strings suitable for
# FUZZ_PARAM_STR in the provided stubs. We emit one or more newline-separated
# entries so fuzzers that split by lines or reuse buffers get multiple options.
# The content focuses on realistic, diverse, but valid forms: hostnames, nicks
# with ident@host, wildcards, CIDR-like, IPv6, Unicode puny-like labels, and
# lengths near limits used by the stubs (e.g., 16/32/48/64/128 chars).

MAX_BYTES = 4096

ALNUM = string.ascii_letters + string.digits
LABEL_CHARS = ALNUM + "-"
USER_CHARS = ALNUM + "-_."


def _rand_label(r: random.Random, min_len=1, max_len=10) -> str:
    n = r.randint(min_len, max_len)
    # Ensure label doesn't start or end with '-'
    core = ''.join(r.choice(LABEL_CHARS) for _ in range(n))
    if core and core[0] == '-':
        core = 'a' + core[1:]
    if core and core[-1] == '-':
        core = core[:-1] + 'z'
    return core.lower()


def _rand_hostname(r: random.Random) -> str:
    # 2-6 labels, typical TLD endings
    tlds = ["com", "net", "org", "io", "example", "local", "xn--p1ai"]
    parts = [_rand_label(r, 1, r.randint(3, 10)) for _ in range(r.randint(2, 6))]
    parts[-1] = r.choice(tlds)
    return '.'.join(parts)


def _rand_ipv4(r: random.Random) -> str:
    return '.'.join(str(r.randint(0, 255)) for _ in range(4))


def _rand_ipv6(r: random.Random) -> str:
    # Generate compressed or full IPv6
    def hextet():
        return format(r.randrange(0, 1 << 16), 'x')
    if r.random() < 0.5:
        return ':'.join(hextet() for _ in range(8))
    # compressed with ::
    left = [hextet() for _ in range(r.randint(0, 4))]
    right = [hextet() for _ in range(r.randint(0, 4))]
    return (':'.join(left) + ('::' if left or right else '::') + ':'.join(right)).replace(':::', '::')


def _rand_ident(r: random.Random) -> str:
    n = r.randint(1, 12)
    s = ''.join(r.choice(USER_CHARS) for _ in range(n))
    # ensure it starts with a letter to be IRC-friendly
    if not s[0].isalpha():
        s = 'u' + s[1:]
    return s


def _wildcard_label(r: random.Random) -> str:
    # produce labels with * wildcard, e.g., *.example.com or 192.168.*
    if r.random() < 0.5:
        return '*'
    # mix literal and wildcard
    base = _rand_label(r, 1, 8)
    if r.random() < 0.5:
        return '*' + base
    return base + '*'


def _rand_wildcard_host(r: random.Random) -> str:
    if r.random() < 0.5:
        # DNS-style wildcard
        return '*.' + _rand_hostname(r)
    # IPv4-style wildcard segment
    octets: List[str] = []
    for i in range(4):
        if r.random() < 0.25:
            octets.append('*')
        else:
            octets.append(str(r.randint(0, 255)))
    return '.'.join(octets)


def _rand_cidr(r: random.Random) -> str:
    if r.random() < 0.6:
        return f"{_rand_ipv4(r)}/{r.randint(8, 32)}"
    return f"{_rand_ipv6(r)}/{r.randint(16, 128)}"


def _bounded(s: str, maxlen: int, r: random.Random) -> str:
    if len(s) <= maxlen:
        return s
    # Ellipsize-like: keep start and end
    if maxlen <= 3:
        return s[:maxlen]
    head = maxlen - 3
    return s[:head] + '...'


def _nick_ident_host(r: random.Random) -> str:
    # nick!ident@host or ident@host or just user@host
    nick = _rand_label(r, 1, 9)
    ident = _rand_ident(r)
    host = _rand_hostname(r) if r.random() < 0.7 else _rand_ipv4(r)
    form = r.random()
    if form < 0.33:
        return f"{ident}@{host}"
    elif form < 0.66:
        return f"{nick}!{ident}@{host}"
    else:
        # host-only acceptable too
        return host


def _near_length_case(target_len: int, r: random.Random) -> str:
    # craft a host close to a given target length
    base = _rand_hostname(r)
    # pad with sublabels to approach target
    while len(base) < target_len:
        add = _rand_label(r, 1, 10)
        candidate = add + '.' + base
        if len(candidate) > target_len:
            break
        base = candidate
    return base[:target_len]


def _unicode_like_label(r: random.Random) -> str:
    # Use punycode-ish ascii with xn-- prefix to stay ASCII but exercise paths
    base = _rand_label(r, 3, 10)
    return 'xn--' + base


def _rand_entry(r: random.Random) -> str:
    choice = r.random()
    if choice < 0.12:
        return _rand_hostname(r)
    if choice < 0.24:
        return _rand_ipv4(r)
    if choice < 0.36:
        return _rand_ipv6(r)
    if choice < 0.48:
        return _rand_wildcard_host(r)
    if choice < 0.60:
        return _rand_cidr(r)
    if choice < 0.72:
        return _nick_ident_host(r)
    if choice < 0.84:
        # unicode-like with wildcard
        return _unicode_like_label(r) + '.' + _rand_hostname(r)
    # near-length boundary cases used by stubs (16/32/48/64/128)
    target = r.choice([16, 32, 48, 64, 128])
    return _near_length_case(target, r)


def _dedupe_preserve_order(items: List[str]) -> List[str]:
    seen = set()
    out = []
    for s in items:
        if s in seen:
            continue
        seen.add(s)
        out.append(s)
    return out


def generate(seed: int) -> bytes:
    r = random.Random(seed)

    entries: List[str] = []

    # Include some deterministic useful seeds first
    entries.extend([
        "irc.example.tld",
        "*.example.org",
        "192.168.*",
        "10.0.0.0/8",
        "user@example.net",
        "nick!ident@host.tld",
        "2001:db8::/32",
    ])

    # Add a variety of random valid forms
    for _ in range(25 + r.randint(0, 25)):
        s = _rand_entry(r)
        # Apply occasional bounding to mimic Trim/Ellipsize behavior targets use
        maxlen = r.choice([16, 24, 32, 48, 64, 80, 96, 128])
        s = _bounded(s, maxlen, r)
        if not s:
            continue
        entries.append(s)

    # Ensure at least one very long but valid hostmask to test truncation
    long_host = '.'.join(_rand_label(r, 5, 10) for _ in range(20)) + '.com'
    entries.append(_bounded(long_host, 256, r))

    # Deduplicate while preserving order
    entries = _dedupe_preserve_order(entries)

    # Join as newline-separated so consumers can read one or many strings
    data = ('\n'.join(entries) + '\n').encode('utf-8', errors='ignore')

    if len(data) > MAX_BYTES:
        data = data[:MAX_BYTES]
        # Ensure last line ends cleanly
        last_nl = data.rfind(b"\n")
        if last_nl != -1:
            data = data[: last_nl + 1]
    return data

import os
import random
import struct
from typing import List, Tuple

# Generator for ZNC configuration text (znc.conf-like)
# Targets fuzzer stubs:
# - CZNC::ParseConfig: consumes a raw configuration string
# - CUser::ParseConfig: code creates its own CConfig, but realistic keys help
# - CConfig::Parse: reads a file; our buffer will be used as file contents
# We therefore emit plausible znc.conf text exercising keys, values, and sections.

# Notes on znc.conf format (simplified):
# - Top-level key = value (space separated), e.g., LoadModule = webadmin
# - Quoted values allowed; comments start with #
# - Nested sections use <Section "Name"> ... </Section>
#   common sections: User, Network, Listener, LoadModule, Chan, CTCP, Pass, etc.
# - Within User/Network blocks, inner keys (Nick, AltNick, Ident, Server, Chan, Key, etc.)
# - Boolean values like true/false, numbers for ports, limits.

MAX_SIZE = 4096

BOOLS = ["true", "false", "on", "off", "yes", "no"]
MODULES = [
    "webadmin", "controlpanel", "chanfilter", "partyline", "sasl",
    "simple_away", "adminlog", "log", "nickserv", "perform",
]
CAPS = [
    "multi-prefix", "userhost-in-names", "away-notify", "server-time",
    "batch", "labeled-response", "message-tags", "sasl"
]
ENCODINGS = ["UTF-8", "ISO-8859-1", "KOI8-R", "CP1251", "ISO-2022-JP"]
LANGS = ["en_US", "de_DE", "ru_RU", "fr_FR", "es_ES"]

def rchoice(r: random.Random, seq: List[str]) -> str:
    return seq[r.randrange(len(seq))]

def rnd_ident(r: random.Random, min_len=3, max_len=12) -> str:
    letters = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_-"
    n = r.randint(min_len, max_len)
    s = r.choice("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ")
    s += "".join(r.choice(letters) for _ in range(n - 1))
    return s

def rnd_host(r: random.Random) -> str:
    if r.random() < 0.2:
        # IPv6
        parts = [format(r.getrandbits(16), 'x') for _ in range(8)]
        return ":".join(parts)
    else:
        # hostname
        labels = [rnd_ident(r, 1, r.randint(3, 8)).lower() for _ in range(r.randint(2, 4))]
        tld = rchoice(r, ["com", "net", "org", "io", "dev", "local"])
        return ".".join(labels + [tld])

def rnd_port(r: random.Random) -> int:
    return r.choice([6667, 6697, 7000, 6669, r.randint(1025, 65535)])

def rnd_channel(r: random.Random) -> str:
    prefix = r.choice(["#", "&"]) if r.random() < 0.9 else "+"
    name = rnd_ident(r, 3, 12)
    return prefix + name

def kv(key: str, value: str) -> str:
    # Quote if value has spaces or special chars
    if any(c.isspace() for c in value) or any(c in value for c in ['"', '<', '>', '#']):
        v = '"' + value.replace('"', '\\"') + '"'
    else:
        v = value
    return f"{key} = {v}\n"

def section(tag: str, name: str, body: str) -> str:
    name_part = f' "{name}"' if name else ""
    return f"<{tag}{name_part}>\n{body}</{tag}>\n"

def gen_listener(r: random.Random) -> str:
    lines = []
    lines.append(kv("Port", str(rnd_port(r))))
    if r.random() < 0.8:
        lines.append(kv("SSL", rchoice(r, BOOLS)))
    if r.random() < 0.5:
        lines.append(kv("IPv6", rchoice(r, BOOLS)))
    if r.random() < 0.5:
        lines.append(kv("BindHost", rnd_host(r)))
    if r.random() < 0.5:
        lines.append(kv("URIPrefix", "/" + rnd_ident(r, 3, 8)))
    if r.random() < 0.5:
        lines.append(kv("AcceptType", rchoice(r, ["IRC", "HTTP", "ALL"])) )
    return section("Listener", "", "".join(lines))

def gen_servers(r: random.Random) -> List[str]:
    servers = []
    for _ in range(r.randint(1, 3)):
        host = rnd_host(r)
        port = rnd_port(r)
        passw = "" if r.random() < 0.7 else rnd_ident(r, 6, 12)
        ssl = r.random() < 0.5
        unix = r.random() < 0.1
        parts = [host, str(port)]
        if passw:
            parts.append(passw)
        if ssl:
            parts.append("SSL")
        if unix:
            parts.append("UNIX")
        servers.append(" ".join(parts))
    return servers

def gen_network_block(r: random.Random) -> str:
    name = rnd_ident(r, 3, 10)
    lines = []
    # Identity
    if r.random() < 0.8:
        lines.append(kv("Nick", rnd_ident(r, 4, 10)))
    if r.random() < 0.5:
        lines.append(kv("AltNick", rnd_ident(r, 4, 10)))
    if r.random() < 0.7:
        lines.append(kv("Ident", rnd_ident(r, 4, 10)))
    if r.random() < 0.6:
        lines.append(kv("RealName", rnd_ident(r, 6, 16)))
    # Encoding/timezone
    if r.random() < 0.5:
        lines.append(kv("Encoding", rchoice(r, ENCODINGS)))
    if r.random() < 0.4:
        lines.append(kv("Timezone", rchoice(r, LANGS)))
    # Flood/burst
    if r.random() < 0.5:
        lines.append(kv("FloodRate", f"{r.uniform(0.5, 5.0):.2f}"))
    if r.random() < 0.5:
        lines.append(kv("FloodBurst", str(r.randint(1, 20))))
    # Join delay
    if r.random() < 0.4:
        lines.append(kv("JoinDelay", str(r.randint(0, 30))))
    # Servers
    for s in gen_servers(r):
        lines.append(kv("Server", s))
    # Channels
    for _ in range(r.randint(0, 4)):
        chan_body = []
        chan_name = rnd_channel(r)
        if r.random() < 0.5:
            chan_body.append(kv("Key", rnd_ident(r, 4, 10)))
        if r.random() < 0.6:
            chan_body.append(kv("Buffer", str(r.randint(0, 500))))
        if r.random() < 0.5:
            chan_body.append(kv("Detached", rchoice(r, BOOLS)))
        lines.append(section("Chan", chan_name, "".join(chan_body)))
    # Perform
    if r.random() < 0.6:
        for _ in range(r.randint(0, 3)):
            lines.append(kv("Perform", "/msg NickServ IDENTIFY secret"))
    # Caps desired
    if r.random() < 0.5:
        caplist = ",".join(r.sample(CAPS, r.randint(1, min(4, len(CAPS)))))
        lines.append(kv("RequestCapability", caplist))
    return section("Network", name, "".join(lines))

def gen_pass_block(r: random.Random) -> str:
    # ZNC supports Pass with Hash and Method; keep it simple but valid-ish.
    body = []
    method = rchoice(r, ["plain", "sha256", "md5"])
    body.append(kv("Method", method))
    # For hashed methods, provide Salt and Hash; for plain, provide Password
    if method == "plain":
        body.append(kv("Password", rnd_ident(r, 8, 16)))
    else:
        body.append(kv("Salt", rnd_ident(r, 8, 12)))
        body.append(kv("Hash", rnd_ident(r, 16, 32)))
    return section("Pass", "", "".join(body))

def gen_user_block(r: random.Random) -> str:
    name = rnd_ident(r, 3, 10)
    lines = []
    # Admin and permissions
    if r.random() < 0.7:
        lines.append(kv("Admin", rchoice(r, BOOLS)))
    if r.random() < 0.6:
        lines.append(kv("DenyLoadMod", rchoice(r, BOOLS)))
    if r.random() < 0.6:
        lines.append(kv("MultiClients", rchoice(r, BOOLS)))
    if r.random() < 0.5:
        lines.append(kv("MaxNetworks", str(r.randint(1, 20))))
    # Identity defaults
    if r.random() < 0.8:
        lines.append(kv("Nick", rnd_ident(r, 4, 10)))
    if r.random() < 0.7:
        lines.append(kv("AltNick", rnd_ident(r, 4, 10)))
    if r.random() < 0.7:
        lines.append(kv("Ident", rnd_ident(r, 4, 10)))
    if r.random() < 0.6:
        lines.append(kv("RealName", rnd_ident(r, 8, 16)))
    if r.random() < 0.5:
        lines.append(kv("ClientEncoding", rchoice(r, ENCODINGS)))
    if r.random() < 0.5:
        lines.append(kv("Timezone", rchoice(r, LANGS)))
    # Status prefix and language
    if r.random() < 0.5:
        lines.append(kv("StatusPrefix", rchoice(r, ["*", "!status", "&"])) )
    if r.random() < 0.5:
        lines.append(kv("Language", rchoice(r, LANGS)))
    # Buffers
    if r.random() < 0.6:
        lines.append(kv("ChanBufferSize", str(r.randint(0, 500))))
    if r.random() < 0.6:
        lines.append(kv("QueryBufferSize", str(r.randint(0, 500))))
    # Allowed hosts (hostmasks)
    for _ in range(r.randint(0, 3)):
        mask = f"*@{rnd_host(r)}"
        lines.append(kv("Allow", mask))
    # Load some modules for user
    for _ in range(r.randint(0, 3)):
        lines.append(kv("LoadModule", rchoice(r, MODULES)))
    # Password block
    if r.random() < 0.9:
        lines.append(gen_pass_block(r))
    # Networks
    nnet = r.randint(0, 3)
    for _ in range(nnet):
        lines.append(gen_network_block(r))
    return section("User", name, "".join(lines))

def gen_global_top(r: random.Random) -> str:
    lines = []
    # Basic global settings
    if r.random() < 0.7:
        lines.append(kv("AnonIPLimit", str(r.randint(0, 50))))
    if r.random() < 0.7:
        lines.append(kv("ServerThrottle", str(r.randint(0, 60))))
    if r.random() < 0.6:
        lines.append(kv("ProtectWebSessions", rchoice(r, BOOLS)))
    if r.random() < 0.6:
        lines.append(kv("HideVersion", rchoice(r, BOOLS)))
    if r.random() < 0.6:
        lines.append(kv("AuthOnlyViaModule", rchoice(r, BOOLS)))
    if r.random() < 0.5:
        lines.append(kv("ConfigWriteDelay", str(r.randint(0, 600))))
    if r.random() < 0.5:
        lines.append(kv("SSLCiphers", "TLSv1.3:TLSv1.2+AESGCM"))
    if r.random() < 0.5:
        lines.append(kv("SSLProtocols", "TLSv1.3,TLSv1.2"))
    # MOTD (multi-line allowed as repeated key)
    for _ in range(r.randint(0, 3)):
        lines.append(kv("Motd", f"Welcome {rnd_ident(r, 3, 8)}"))
    # Trusted proxies
    for _ in range(r.randint(0, 2)):
        lines.append(kv("TrustedProxy", rnd_host(r)))
    # Load some global modules
    for _ in range(r.randint(0, 3)):
        lines.append(kv("LoadModule", rchoice(r, MODULES)))
    return "".join(lines)

def assemble_config(r: random.Random) -> str:
    parts: List[str] = []
    # Header comment
    parts.append("# Auto-generated ZNC configuration\n")
    # Some listeners
    for _ in range(r.randint(0, 2)):
        parts.append(gen_listener(r))
    # Global keys
    parts.append(gen_global_top(r))
    # Users
    nusers = r.randint(1, 3)
    for _ in range(nusers):
        parts.append(gen_user_block(r))
    cfg = "".join(parts)
    # Ensure size limit
    if len(cfg) > MAX_SIZE:
        cfg = cfg[:MAX_SIZE]
        # Make sure we end on a newline to not cut a tag mid-line too badly
    if not cfg.endswith("\n"):
        cfg += "\n"
    return cfg


def generate(seed: int) -> bytes:
    r = random.Random(seed)
    cfg = assemble_config(r)
    return cfg.encode("utf-8")

import random
import string
from typing import List

# Data type: hostname or IP address (IPv4/IPv6)
# Target stubs use FUZZ_PARAM_STR for hosts, IPs, identifiers, server specs, etc.
# We generate a single bytes buffer that the fuzzing framework will use as the
# initial content for FUZZ_PARAM_STR / FUZZ_PARAM_FILENAME. Keep it valid and
# varied while under 4096 bytes.

HOST_LABEL_CHARS = string.ascii_lowercase + string.digits + "-"
HEX = string.hexdigits.lower()


def rand_ipv4(r: random.Random) -> str:
    # Avoid 0 and 255 in last octet occasionally to hit common real ranges
    octets = []
    for i in range(4):
        if i == 3 and r.random() < 0.5:
            octets.append(str(r.randint(1, 254)))
        else:
            octets.append(str(r.randint(0, 255)))
    return ".".join(octets)


def rand_ipv6(r: random.Random) -> str:
    # Generate different IPv6 forms: full, compressed, IPv4-mapped
    mode = r.choice(["full", "compressed", "mapped"])
    if mode == "full":
        groups = ["".join(r.choice(HEX[:16]) for _ in range(4)) for _ in range(8)]
        return ":".join(groups)
    if mode == "mapped":
        # ::ffff:192.0.2.1 style
        return "::ffff:" + rand_ipv4(r)
    # compressed
    # Build 8 groups, then compress a random run of zero groups
    groups = []
    zero_runs: List[int] = []
    for _ in range(8):
        if r.random() < 0.35:
            groups.append("0")
        else:
            groups.append("".join(r.choice(HEX[:16]) for _ in range(r.randint(1,4))))
    # Find runs of zeros
    best_start = -1
    best_len = 0
    start = -1
    for i,g in enumerate(groups + [None]):
        if g == "0":
            if start == -1:
                start = i
        else:
            if start != -1:
                length = i - start
                if length > best_len:
                    best_len = length
                    best_start = start
                start = -1
    if best_len >= 2:
        left = groups[:best_start]
        right = groups[best_start+best_len:]
        return (":".join(left) if left else "") + "::" + (":".join(right) if right else "")
    else:
        return ":".join(groups)


def rand_hostname(r: random.Random) -> str:
    # Generate DNS-like hostname with 1-5 labels, each 1-63 chars, total <= 253
    labels = []
    nlabels = r.randint(1, 5)
    for i in range(nlabels):
        lmin = 1
        lmax = r.randint(1, 20)
        L = r.randint(lmin, lmax)
        if L == 1:
            label = r.choice(string.ascii_lowercase + string.digits)
        else:
            # First and last must be alnum; middle can include '-'
            mid_len = L - 2
            mid = "".join(r.choice(HOST_LABEL_CHARS) for _ in range(mid_len)) if mid_len > 0 else ""
            label = r.choice(string.ascii_lowercase + string.digits) + mid + r.choice(string.ascii_lowercase + string.digits)
        labels.append(label)
    host = ".".join(labels)
    # Occasionally append a common TLD if not present
    if r.random() < 0.4 and not host.endswith(tuple([".com",".net",".org",".local",".lan"])):
        host += r.choice([".com",".net",".org",".local",".lan"])
    return host[:253]


def rand_host_or_ip(r: random.Random) -> str:
    kind = r.choices(["ipv4","ipv6","host"], weights=[4,3,6], k=1)[0]
    if kind == "ipv4":
        return rand_ipv4(r)
    if kind == "ipv6":
        return rand_ipv6(r)
    return rand_hostname(r)


def maybe_port(r: random.Random) -> str:
    # Sometimes include :port as some stubs accept host:port specs
    if r.random() < 0.45:
        port = r.randint(1, 65535)
        return f":{port}"
    return ""


def maybe_credentials(r: random.Random) -> str:
    # Occasionally prefix with user[:pass]@ part for URL-like specs (some code may parse it)
    if r.random() < 0.15:
        user = ''.join(r.choice(string.ascii_lowercase+string.digits) for _ in range(r.randint(3,8)))
        if r.random() < 0.5:
            passwd = ''.join(r.choice(string.ascii_letters+string.digits+"-_.") for _ in range(r.randint(3,8)))
            return f"{user}:{passwd}@"
        return f"{user}@"
    return ""


def build_candidates(r: random.Random) -> List[str]:
    c: List[str] = []
    # Plain host/IP
    for _ in range(6):
        c.append(rand_host_or_ip(r))
    # host:port and [ipv6]:port variants
    for _ in range(4):
        h = rand_host_or_ip(r)
        if ":" in h and not h.count(":") == 1:  # likely IPv6
            if r.random() < 0.8:
                h = f"[{h}]"  # bracket for host:port compliance
        c.append(h + maybe_port(r))
    # URI-like prefixes used by SetIRCServer or Connect specs
    schemes = ["irc://", "ircs://", "http://", "https://"]
    for _ in range(3):
        h = rand_host_or_ip(r)
        if ":" in h and not h.count(":") == 1:
            h_disp = f"[{h}]"
        else:
            h_disp = h
        c.append(r.choice(schemes) + maybe_credentials(r) + h_disp + maybe_port(r))
    # Common literals used in stubs
    c.extend([
        "127.0.0.1",
        "0.0.0.0",
        "::1",
        "localhost",
        "znc.example.net",
        "2001:db8::1",
    ])
    # Deduplicate while preserving order
    seen = set()
    out = []
    for s in c:
        if s not in seen and s:
            seen.add(s)
            out.append(s)
    return out


def pack_strings(strs: List[str]) -> bytes:
    # Simple newline-separated list; FUZZ harness typically reads one FUZZ_PARAM_STR at a time
    data = ("\n".join(strs)).encode("utf-8", errors="ignore")
    return data[:4096]


def generate(seed: int) -> bytes:
    r = random.Random(seed)
    candidates = build_candidates(r)
    # Shuffle to vary first entries which many fuzzers consume earlier
    r.shuffle(candidates)
    return pack_strings(candidates)

import random
import string

# Target: generate valid free-form text inputs for many fuzz stubs using FUZZ_PARAM_STR / FUZZ_PARAM_FILENAME.
# Strategy: produce a compact, interesting corpus element that exercises a variety of
# realistic strings used by ZNC: IRC-like lines, module names, caps, cookie-like pairs,
# web paths, channel names, base64 blocks, numbers, and Unicode. All in a single buffer
# separated by newlines, so the harness can split or slice as needed. We keep it <= 4096 bytes.

SAFE_ASCII = string.ascii_letters + string.digits + "-_.:/#[]@!$%^&*(){}|?=+~,;\"'"

UNICODE_SAMPLES = [
    "Привет", "こんにちは", "你好", "안녕", "γειά", "مرحبا", "שלום",
    "😀😺🔥✨", "€£¥₿", "ñáéíóúç", "ßØÅåø«,»", "Δοκιμή",
]

CAP_NAMES = [
    "server-time", "batch", "message-tags", "account-notify", "away-notify",
    "invite-notify", "echo-message", "labeled-response", "sasl", "chghost"
]

MODULE_NAMES = [
    "webadmin", "kickrejoin", "sasl", "chansaver", "nickserv", "route_replies",
    "controlpanel", "log", "lastlog", "autoop", "simple_away"
]

def rand_ascii(rng, min_len, max_len):
    n = rng.randint(min_len, max_len)
    return ''.join(rng.choice(SAFE_ASCII) for _ in range(n))

def rand_unicode(rng, min_len, max_len):
    # Mix ASCII with random unicode samples
    parts = []
    total = rng.randint(min_len, max_len)
    while len(''.join(parts)) < total:
        if rng.random() < 0.5:
            parts.append(rand_ascii(rng, 1, 6))
        else:
            parts.append(rng.choice(UNICODE_SAMPLES))
    s = ''.join(parts)
    return s[:total]

def rand_channel(rng):
    name = rng.choice(['#', '&']) + rand_ascii(rng, 3, 16)
    return name

def rand_nick(rng):
    base = rng.choice(string.ascii_letters) + ''.join(rng.choice(string.ascii_letters + string.digits + "-_") for _ in range(rng.randint(2,10)))
    return base

def rand_hostname(rng):
    labels = [
        ''.join(rng.choice(string.ascii_lowercase + string.digits) for _ in range(rng.randint(1, 10)))
        for _ in range(rng.randint(2, 4))
    ]
    return '.'.join(labels)

def rand_path(rng):
    segs = [rand_ascii(rng, 1, 6) for _ in range(rng.randint(1, 4))]
    return "/" + "/".join(segs)

def rand_cookie(rng):
    k = rand_ascii(rng, 3, 10)
    v = rand_ascii(rng, 3, 12)
    return f"{k}={v}"

def rand_base64(rng, min_bytes=1, max_bytes=32):
    import base64
    raw = rng.randbytes(rng.randint(min_bytes, max_bytes)) if hasattr(rng, 'randbytes') else bytes([rng.randrange(256) for _ in range(rng.randint(min_bytes, max_bytes))])
    return base64.b64encode(raw).decode('ascii')

def rand_numeric(rng):
    if rng.random() < 0.5:
        return str(rng.randint(0, 100000))
    else:
        return f"{rng.uniform(-1000, 1000):.3f}"

def rand_irc_line(rng):
    # ":nick!ident@host PRIVMSG #chan :text"
    nick = rand_nick(rng)
    ident = rand_ascii(rng, 3, 8)
    host = rand_hostname(rng)
    cmd = rng.choice(["PRIVMSG","NOTICE","JOIN","PART","TOPIC","QUIT","MODE","PING","PONG","NICK","001","372"]) 
    params = []
    if cmd in ("PRIVMSG","NOTICE"):
        params = [rand_channel(rng), rand_unicode(rng, 1, 40)]
    elif cmd == "JOIN":
        params = [rand_channel(rng)] + ([rand_ascii(rng, 3, 8)] if rng.random()<0.4 else [])
    elif cmd == "PART":
        params = [rand_channel(rng), rand_unicode(rng, 0, 20)]
    elif cmd == "TOPIC":
        params = [rand_channel(rng), rand_unicode(rng, 0, 40)]
    elif cmd == "QUIT":
        params = [rand_unicode(rng, 0, 30)]
    else:
        for _ in range(rng.randint(0,3)):
            params.append(rand_ascii(rng, 1, 12))
    middle = ''
    if params:
        if len(params) == 1:
            middle = f" {params[0]}"
        else:
            middle = ' ' + ' '.join(params[:-1]) + f" :{params[-1]}"
    return f":{nick}!{ident}@{host} {cmd}{middle}"

def rand_cap(rng):
    cap = rng.choice(CAP_NAMES)
    if rng.random() < 0.5:
        # With value
        val = rand_ascii(rng, 1, 10)
        return f"{cap}={val}"
    return cap

def rand_module_line(rng):
    name = rng.choice(MODULE_NAMES)
    args = rand_ascii(rng, 0, 20)
    return f"loadmod {name} {args}".strip()

def rand_cfg_pair(rng):
    k = rand_ascii(rng, 3, 10)
    v = rand_unicode(rng, 0, 24)
    return f"{k} = {v}"

def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    parts = []

    # Web/HTTP related
    parts.append(rand_path(rng))                     # URI path
    parts.append(rand_cookie(rng))                   # Cookie

    # IRC-related
    parts.append(rand_irc_line(rng))                 # Raw IRC line
    parts.append(rand_channel(rng))                  # Channel name
    parts.append(rand_nick(rng))                     # Nick

    # Capabilities and SASL
    parts.append(f"CAP LS :{rand_cap(rng)}")
    parts.append(f"AUTHENTICATE {rand_base64(rng)}")

    # Module / status commands
    parts.append(rand_module_line(rng))
    parts.append("help")

    # Config-like pairs
    for _ in range(3):
        parts.append(rand_cfg_pair(rng))

    # Filenames for UNIX listener and file APIs
    fname_core = "/tmp/" + rand_ascii(rng, 5, 10)
    parts.append(fname_core)

    # Translation context examples
    parts.append("t:Hello {1}, number {2}")

    # Base64 block and its decode marker
    b64 = rand_base64(rng, 8, 24)
    parts.append(b64)

    # Numeric strings
    parts.append(rand_numeric(rng))

    # Some Unicode-rich free-form lines
    for _ in range(3):
        parts.append(rand_unicode(rng, 5, 40))

    # A couple of key=value tags line
    parts.append("tag1=val1;tag2=" + rand_ascii(rng, 1, 8))

    # Ensure non-empty message string for broadcast/MOTD
    motd = "Welcome to ZNC: " + rand_unicode(rng, 5, 40)
    parts.append(motd)

    # Constrain total size <= 4096
    blob = "\n".join(parts)
    if len(blob.encode('utf-8')) > 4096:
        # Trim gracefully on character boundary
        enc = blob.encode('utf-8')[:4096]
        # Ensure not cutting multibyte
        try:
            blob = enc.decode('utf-8', errors='ignore')
        except Exception:
            blob = enc.decode('utf-8', errors='ignore')

    return blob.encode('utf-8')

import random
import string

# Data type: ZNC module name (short identifier without path separators)
# This generator returns a bytes buffer intended for FUZZ_PARAM_STR / FUZZ_PARAM_FILENAME
# calls in the provided stubs. We focus on producing module names and related
# argument strings that are valid and exercise different code paths.

RESERVED_COMMON = [
    "webadmin", "sasl", "buffextras", "chansaver", "controlpanel",
    "lastseen", "nickserv", "notes", "partyline", "simple_away",
    "perform", "route_replies", "watch", "adminlog", "block_motd",
]

# Some names with characters often seen in module ecosystems but still safe
# (letters, digits, underscore, dash). Avoid path separators or dots.
THEMES = [
    "mod", "test", "alpha", "beta", "gamma", "delta", "net",
    "user", "global", "irc", "sock", "http", "ssl", "cap",
]

SAFE_CHARS = string.ascii_lowercase + string.digits + "_-"


def _rand_ident(rng: random.Random, min_len: int = 1, max_len: int = 24) -> str:
    n = rng.randint(min_len, max_len)
    # Ensure starts with a letter to satisfy typical expectations
    first = rng.choice(string.ascii_lowercase)
    rest = "".join(rng.choice(SAFE_CHARS) for _ in range(n - 1))
    return first + rest


def _pick_module_name(rng: random.Random) -> str:
    mode = rng.randint(0, 6)
    if mode == 0 and RESERVED_COMMON:
        return rng.choice(RESERVED_COMMON)
    if mode == 1:
        # Compose of theme + number/variant
        base = rng.choice(THEMES)
        suffix = rng.choice(["", "_mod", "-mod", "_v", "-v"]) + (
            str(rng.randint(1, 9)) if rng.random() < 0.8 else ""
        )
        name = base + suffix
        # sanitize double separators
        return name.strip("-_") or "mod"
    if mode == 2:
        # Underscore-heavy but valid
        parts = [_rand_ident(rng, 2, 6) for _ in range(rng.randint(2, 4))]
        return "_".join(parts)
    if mode == 3:
        # Dash-separated tokens
        parts = [_rand_ident(rng, 2, 6) for _ in range(rng.randint(2, 3))]
        return "-".join(parts)
    if mode == 4:
        # Short simple
        return _rand_ident(rng, 3, 8)
    if mode == 5:
        # Maximal length
        return _rand_ident(rng, 10, 32)[:32]
    # Fallback
    return _rand_ident(rng)


def _rand_args(rng: random.Random) -> str:
    # Many modules accept key=value or simple words; keep safe ASCII without newlines
    keys = ["nick", "user", "pass", "network", "chan", "path", "host", "port"]
    items = []
    for _ in range(rng.randint(0, 4)):
        k = rng.choice(keys)
        # values avoid spaces where possible, sometimes quoted
        val_base = _rand_ident(rng, 3, 10)
        if k in ("port"):
            v = str(rng.randint(1, 65535))
        elif k in ("chan",):
            # channel-like but not starting with '#', as args not paths
            v = _rand_ident(rng, 3, 10)
        else:
            v = val_base
        if rng.random() < 0.25:
            v = f"\"{v}\""
        items.append(f"{k}={v}")
    # Sometimes modules take positional args
    if rng.random() < 0.5:
        items.extend(_rand_ident(rng, 3, 8) for _ in range(rng.randint(0, 2)))
    s = " ".join(items)
    # Limit sizes used by stubs (common limits 256/512)
    return s[:256]


def _compose_multifield_blob(rng: random.Random) -> bytes:
    # Many stubs call FUZZ_PARAM_STR multiple times; pack multiple
    # newline-separated strings so the harness can split in order.
    # Order: module, user, args, module_path_hint
    mod = _pick_module_name(rng)
    # usernames in ZNC: letters/digits/underscore; keep simple and short
    user = _rand_ident(rng, 3, 12)
    args = _rand_args(rng)
    # Path hint for GetModPathInfo uses FUZZ_PARAM_FILENAME; provide a safe filename-ish token
    # Avoid slashes to keep within harness expectations; just a name that looks like a .so
    path_token = _pick_module_name(rng) + ("_mod" if rng.random() < 0.5 else "")
    so = (path_token[:20] or "mod") + ".so"

    fields = [mod, user, args, so]
    blob = "\n".join(fields)
    return blob.encode("utf-8")


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # Randomly choose one of several layouts to feed different stubs:
    #  - single module name
    #  - module name + args
    #  - module name + user
    #  - multi-field blob (module, user, args, filename)
    choice = rng.randint(0, 3)
    if choice == 0:
        return _pick_module_name(rng).encode("utf-8")
    elif choice == 1:
        mod = _pick_module_name(rng)
        args = _rand_args(rng)
        return f"{mod}\n{args}".encode("utf-8")
    elif choice == 2:
        mod = _pick_module_name(rng)
        user = _rand_ident(rng, 3, 12)
        return f"{mod}\n{user}".encode("utf-8")
    else:
        return _compose_multifield_blob(rng)

import random
import string
from typing import List

# Generate valid IRC command lines suitable for CClient/CIRCSock/CIRCNetwork paths.
# We focus on realistic commands and formats, respecting typical 512-byte limits and
# avoiding CR/LF. The output is a bytes buffer containing one line (without CRLF),
# which the fuzzing harness will pass to FUZZ_PARAM_STR()/filename as needed.

MAX_LEN = 510  # typical IRC payload limit without CRLF

CMDS_WITH_TARGET_TEXT = [
    ("PRIVMSG", True),
    ("NOTICE", True),
]
CMDS_SIMPLE = [
    "PING", "PONG", "QUIT", "NICK", "USER", "OPER", "PASS",
]
NUMERICS = ["001", "005", "372", "375", "376", "433", "451", "462"]

CHAN_PREFIXES = ["#", "&", "+", "!"]

def rch(rs: random.Random, choices: str) -> str:
    return rs.choice(choices)

def rand_ascii(rs: random.Random, min_len: int, max_len: int, extra: str = "") -> str:
    alphabet = string.ascii_letters + string.digits + "-_./[]{}^`" + extra
    n = rs.randint(min_len, max_len)
    return "".join(rs.choice(alphabet) for _ in range(n))

def rand_nick(rs: random.Random) -> str:
    start = rs.choice(string.ascii_letters + "[]{}^_`|\\")
    rest = rand_ascii(rs, 0, 9)
    return (start + rest)[:16]

def rand_ident(rs: random.Random) -> str:
    return rand_ascii(rs, 3, 10)

def rand_host(rs: random.Random) -> str:
    # simple hostname
    labels = [rand_ascii(rs, 1, rs.randint(2, 6)).lower() for _ in range(rs.randint(2, 4))]
    return ".".join(labels)

def rand_chan(rs: random.Random) -> str:
    prefix = rs.choice(CHAN_PREFIXES)
    name = rand_ascii(rs, 1, rs.randint(3, 12))
    return (prefix + name)[:32]

def rand_text(rs: random.Random, max_len: int = 200) -> str:
    # include spaces and common punctuation, avoid CR/LF
    alphabet = string.ascii_letters + string.digits + string.punctuation + " "
    s = "".join(rs.choice(alphabet) for _ in range(rs.randint(1, min(40, max_len))))
    # trim excessive spaces
    return " ".join(s.split())[:max_len]

def build_prefix(rs: random.Random) -> str:
    if rs.random() < 0.7:
        return f":{rand_nick(rs)}!{rand_ident(rs)}@{rand_host(rs)} "
    return ""

def build_params(params: List[str]) -> str:
    if not params:
        return ""
    if len(params) == 1:
        # single trailing param
        return f" :{params[0]}"
    # all but last as middle params, last as trailing
    middle = " ".join(params[:-1])
    return f" {middle} :{params[-1]}"

def build_priv_like(rs: random.Random, cmd: str) -> str:
    target = rand_chan(rs) if rs.random() < 0.6 else rand_nick(rs)
    text = rand_text(rs, 220)
    return f"{cmd} {target} :{text}"

def build_join(rs: random.Random) -> str:
    chan = ",".join({rand_chan(rs) for _ in range(rs.randint(1, 3))})
    if rs.random() < 0.3:
        key = rand_ascii(rs, 3, 10)
        return f"JOIN {chan} {key}"
    return f"JOIN {chan}"

def build_part(rs: random.Random) -> str:
    chan = ",".join({rand_chan(rs) for _ in range(rs.randint(1, 2))})
    if rs.random() < 0.6:
        return f"PART {chan} :{rand_text(rs, 120)}"
    return f"PART {chan}"

def build_mode(rs: random.Random) -> str:
    if rs.random() < 0.5:
        # channel modes
        chan = rand_chan(rs)
        modes = rs.choice(["+nt", "+k", "+im", "+ov", "+b", "+l"])  # examples
        args: List[str] = [chan, modes]
        if "k" in modes:
            args.append(rand_ascii(rs, 4, 8))
        if "l" in modes:
            args.append(str(rs.randint(10, 200)))
        if "o" in modes or "v" in modes:
            args.append(rand_nick(rs))
        return "MODE " + " ".join(args)
    # user modes
    return f"MODE {rand_nick(rs)} +i"

def build_topic(rs: random.Random) -> str:
    return f"TOPIC {rand_chan(rs)} :{rand_text(rs, 200)}"

def build_quit(rs: random.Random) -> str:
    return f"QUIT :{rand_text(rs, 120)}"

def build_pass(rs: random.Random) -> str:
    return f"PASS {rand_ascii(rs, 6, 16)}"

def build_user(rs: random.Random) -> str:
    # USER <user> <mode> * :<realname>
    return f"USER {rand_ident(rs)} 0 * :{rand_text(rs, 60)}"

def build_nick(rs: random.Random) -> str:
    return f"NICK {rand_nick(rs)}"

def build_pingpong(rs: random.Random, cmd: str) -> str:
    token = rand_ascii(rs, 6, 16)
    if rs.random() < 0.5:
        return f"{cmd} :{token}"
    return f"{cmd} {token}"

def build_numeric(rs: random.Random) -> str:
    code = rs.choice(NUMERICS)
    nick = rand_nick(rs)
    params: List[str] = [nick]
    if code == "005":
        middle = ["CHANTYPES=#&", "PREFIX=(ov)@+", "NETWORK=znc", "CASEMAPPING=rfc1459"]
        params.extend(middle)
        params.append("are supported by this server")
    elif code == "372":
        params.append("- Welcome to ZNC MOTD")
    elif code == "001":
        params.append("Welcome")
    else:
        params.append(rand_text(rs, 60))
    line = f"{code}"
    if rs.random() < 0.6:
        line = build_prefix(rs) + line
    return line + build_params(params)

def assemble(rs: random.Random) -> str:
    builders = [
        lambda: build_priv_like(rs, "PRIVMSG"),
        lambda: build_priv_like(rs, "NOTICE"),
        lambda: build_join(rs),
        lambda: build_part(rs),
        lambda: build_mode(rs),
        lambda: build_topic(rs),
        lambda: build_quit(rs),
        lambda: build_pass(rs),
        lambda: build_user(rs),
        lambda: build_nick(rs),
        lambda: build_pingpong(rs, "PING"),
        lambda: build_pingpong(rs, "PONG"),
        lambda: build_numeric(rs),
    ]
    line = builders[rs.randrange(len(builders))]()
    # Optional prefix
    if rs.random() < 0.5 and not line.startswith(":"):
        line = build_prefix(rs) + line
    # Ensure length and remove CR/LF
    line = line.replace("\r", "").replace("\n", "")
    if len(line) > MAX_LEN:
        line = line[:MAX_LEN]
    return line

def generate(seed: int) -> bytes:
    rs = random.Random(seed)
    line = assemble(rs)
    # Return as bytes without CRLF (harness may add or not as needed)
    return line.encode("utf-8", errors="ignore")

import random
import string
from typing import List

# Generator for valid raw IRC message strings suitable for ZNC CMessage parsing.
# It produces a single IRC line (no CR/LF) with optional IRCv3 tags and prefix,
# using a variety of common IRC commands and plausible parameters.

CHAN_PREFIXES = ['#', '&', '+', '!']
USER_CHARS = string.ascii_letters + string.digits + "_-[]\\`^{}"
HOST_CHARS = string.ascii_lowercase + string.digits + ".-"
TAG_KEY_CHARS = string.ascii_lowercase + string.digits + "-/."
CTCP_DELIM = "\x01"

IRC_ESCAPES = {
    ';': '\\:s',
    ' ': '\\s',
    '\\r': '\\r',
    '\\n': '\\n',
    '\\': '\\\\',
}


def _rchoice(rnd: random.Random, seq: List[str]):
    return seq[rnd.randrange(len(seq))]


def rand_nick(rnd: random.Random) -> str:
    n = rnd.randint(1, 12)
    first = rnd.choice(string.ascii_letters)
    rest = ''.join(rnd.choice(USER_CHARS) for _ in range(max(0, n - 1)))
    return first + rest


def rand_ident(rnd: random.Random) -> str:
    n = rnd.randint(3, 10)
    return ''.join(rnd.choice(string.ascii_lowercase + string.digits + "-_") for _ in range(n))


def rand_host(rnd: random.Random) -> str:
    labels = rnd.randint(2, 4)
    parts = []
    for _ in range(labels):
        ln = rnd.randint(1, 8)
        label = ''.join(rnd.choice(string.ascii_lowercase + string.digits + '-') for _ in range(ln)).strip('-')
        parts.append(label or 'host')
    return '.'.join(parts)


def rand_prefix(rnd: random.Random) -> str:
    return f":{rand_nick(rnd)}!{rand_ident(rnd)}@{rand_host(rnd)} "


def rand_chan(rnd: random.Random) -> str:
    p = _rchoice(rnd, CHAN_PREFIXES)
    name_len = rnd.randint(1, 12)
    name = ''.join(rnd.choice(string.ascii_letters + string.digits + "-_") for _ in range(name_len))
    return p + name


def rand_text(rnd: random.Random, min_len=0, max_len=120) -> str:
    ln = rnd.randint(min_len, max_len)
    alphabet = string.ascii_letters + string.digits + string.punctuation + ' '
    s = ''.join(rnd.choice(alphabet) for _ in range(ln))
    return s.replace('\r', ' ').replace('\n', ' ')


def rand_ctcp_text(rnd: random.Random) -> str:
    verb = rnd.choice(["ACTION", "PING", "VERSION", "TIME", "CLIENTINFO"]) if rnd.random() < 0.7 else rand_text(rnd, 3, 8).upper()
    arg = rand_text(rnd, 0, 40).strip()
    inner = verb if not arg else f"{verb} {arg}"
    return f"{CTCP_DELIM}{inner}{CTCP_DELIM}"


def tag_escape(val: str) -> str:
    out = []
    for ch in val:
        if ch in IRC_ESCAPES:
            out.append(IRC_ESCAPES[ch])
        else:
            out.append(ch)
    return ''.join(out)


def rand_tags(rnd: random.Random) -> str:
    n = rnd.randint(1, 5)
    tags = []
    for _ in range(n):
        key_len = rnd.randint(1, 10)
        key = ''.join(rnd.choice(TAG_KEY_CHARS) for _ in range(key_len))
        if rnd.random() < 0.3:
            key = f"vendor/{key}"
        if rnd.random() < 0.75:
            val = rand_text(rnd, 0, 20)
            tags.append(f"{key}={tag_escape(val)}")
        else:
            tags.append(key)
    return '@' + ';'.join(tags) + ' '


def cmd_PRIVMSG(rnd: random.Random) -> str:
    target = rand_chan(rnd) if rnd.random() < 0.6 else rand_nick(rnd)
    text = rand_ctcp_text(rnd) if rnd.random() < 0.2 else rand_text(rnd, 1, 150)
    return f"PRIVMSG {target} :{text}"


def cmd_NOTICE(rnd: random.Random) -> str:
    target = rand_chan(rnd) if rnd.random() < 0.5 else rand_nick(rnd)
    text = rand_ctcp_text(rnd) if rnd.random() < 0.15 else rand_text(rnd, 0, 120)
    return f"NOTICE {target} :{text}"


def cmd_JOIN(rnd: random.Random) -> str:
    target = ','.join(rand_chan(rnd) for _ in range(rnd.randint(1, 3)))
    if rnd.random() < 0.4:
        key = ','.join(rand_text(rnd, 3, 8) for _ in range(target.count(',') + 1))
        return f"JOIN {target} {key}"
    return f"JOIN {target}"


def cmd_PART(rnd: random.Random) -> str:
    ch = rand_chan(rnd)
    if rnd.random() < 0.6:
        return f"PART {ch} :{rand_text(rnd, 0, 80)}"
    return f"PART {ch}"


def cmd_TOPIC(rnd: random.Random) -> str:
    ch = rand_chan(rnd)
    if rnd.random() < 0.5:
        return f"TOPIC {ch} :{rand_text(rnd, 0, 120)}"
    return f"TOPIC {ch}"


def cmd_NICK(rnd: random.Random) -> str:
    return f"NICK {rand_nick(rnd)}"


def cmd_MODE(rnd: random.Random) -> str:
    target = rand_chan(rnd) if rnd.random() < 0.8 else rand_nick(rnd)
    modes = []
    params = []
    for _ in range(rnd.randint(1, 3)):
        sign = '+' if rnd.random() < 0.5 else '-'
        if target and target[0] in CHAN_PREFIXES:
            choice = rnd.random()
            if choice < 0.3:
                modes.append(sign + 'o'); params.append(rand_nick(rnd))
            elif choice < 0.6:
                modes.append(sign + 'v'); params.append(rand_nick(rnd))
            elif choice < 0.8:
                if sign == '+':
                    modes.append(sign + 'k'); params.append(rand_text(rnd, 3, 8))
                else:
                    modes.append(sign + 'k')
            else:
                if sign == '+':
                    modes.append(sign + 'l'); params.append(str(rnd.randint(1, 500)))
                else:
                    modes.append(sign + 'l')
        else:
            modes.append(sign + _rchoice(rnd, list('iwsp')))
    mode_str = ''.join(modes) if modes else '+i'
    line = f"MODE {target} {mode_str}"
    if params:
        line += ' ' + ' '.join(params)
    return line


def cmd_KICK(rnd: random.Random) -> str:
    ch = rand_chan(rnd)
    nicks = ','.join(rand_nick(rnd) for _ in range(rnd.randint(1, 2)))
    if rnd.random() < 0.7:
        return f"KICK {ch} {nicks} :{rand_text(rnd, 0, 60)}"
    return f"KICK {ch} {nicks}"


def cmd_INVITE(rnd: random.Random) -> str:
    return f"INVITE {rand_nick(rnd)} {rand_chan(rnd)}"


def cmd_PING(rnd: random.Random) -> str:
    tok = rand_text(rnd, 1, 16)
    return f"PING :{tok}" if rnd.random() < 0.5 else f"PING {tok}"


def cmd_PONG(rnd: random.Random) -> str:
    tok = rand_text(rnd, 1, 16)
    return f"PONG :{tok}" if rnd.random() < 0.5 else f"PONG {tok}"


def cmd_QUIT(rnd: random.Random) -> str:
    return f"QUIT :{rand_text(rnd, 0, 100)}"


def cmd_ACCOUNT(rnd: random.Random) -> str:
    val = rnd.choice(["*", rand_nick(rnd)])
    return f"ACCOUNT {val}"


def cmd_TAGMSG(rnd: random.Random) -> str:
    target = rand_chan(rnd) if rnd.random() < 0.5 else rand_nick(rnd)
    # TAGMSG must have tags; ensure tags later when assembling
    return f"TAGMSG {target}"


def cmd_AUTHENTICATE(rnd: random.Random) -> str:
    # SASL lines: payload token or '+' continuation
    if rnd.random() < 0.2:
        return "AUTHENTICATE +"
    # Make a base64-like token (not necessarily valid b64, but tokenish)
    alphabet = string.ascii_letters + string.digits + "+/="
    ln = rnd.randint(4, 200)
    tok = ''.join(rnd.choice(alphabet) for _ in range(ln))
    return f"AUTHENTICATE {tok}"


def cmd_NUMERIC(rnd: random.Random) -> str:
    code = rnd.randint(1, 599)
    params = [rand_nick(rnd)]
    if rnd.random() < 0.5:
        params.append(rand_chan(rnd))
    trailing = rand_text(rnd, 0, 80)
    middle = ' '.join(params)
    return f"{code:03d} {middle} :{trailing}" if trailing or middle else f"{code:03d}"


COMMAND_BUILDERS = [
    cmd_PRIVMSG,
    cmd_NOTICE,
    cmd_JOIN,
    cmd_PART,
    cmd_TOPIC,
    cmd_NICK,
    cmd_MODE,
    cmd_KICK,
    cmd_INVITE,
    cmd_PING,
    cmd_PONG,
    cmd_QUIT,
    cmd_ACCOUNT,
    cmd_TAGMSG,
    cmd_AUTHENTICATE,
    cmd_NUMERIC,
]


def build_line(rnd: random.Random) -> str:
    pieces = []
    # Optional tags
    add_tags = rnd.random() < 0.6
    if add_tags:
        pieces.append(rand_tags(rnd))
    # Optional prefix
    if rnd.random() < 0.6:
        pieces.append(rand_prefix(rnd))
    # Command
    builder = rnd.choice(COMMAND_BUILDERS)
    cmdline = builder(rnd)
    pieces.append(cmdline)
    line = ''.join(pieces)
    # Ensure TAGMSG has tags (required by spec)
    if cmdline.startswith('TAGMSG') and not add_tags:
        line = rand_tags(rnd) + line
    # Trim to a safe maximum for the fuzzers (they cap at <= 1024)
    if len(line) > 1000:
        line = line[:1000]
    return line


def generate(seed: int) -> bytes:
    rnd = random.Random(seed)
    # Sometimes generate multiple lines joined by a space-like scenario? No, single line required.
    line = build_line(rnd)
    # Guarantee no CR/LF per single IRC line for fuzzer input (parser in CMessage::Parse reads one line)
    line = line.replace('\r', ' ').replace('\n', ' ')
    # Return as bytes, UTF-8
    return line.encode('utf-8')

import random
import string

# Data type: TLS certificate fingerprint
# We generate colon-separated hex pairs for common digests (SHA-1, SHA-256),
# and also include some variations (no colons, mixed case), as the APIs
# normalize internally.

HEX_DIGITS_UPPER = "0123456789ABCDEF"
HEX_DIGITS_LOWER = "0123456789abcdef"


def _hex_pairs(n_bytes: int, with_colons: bool, upper: bool) -> str:
    digits = HEX_DIGITS_UPPER if upper else HEX_DIGITS_LOWER
    # Produce n_bytes random bytes and render as hex pairs
    bs = [random.getrandbits(8) for _ in range(n_bytes)]
    pairs = [digits[(b >> 4) & 0xF] + digits[b & 0xF] for b in bs]
    if with_colons:
        return ":".join(pairs)
    else:
        return "".join(pairs)


def _sha1_fp() -> str:
    # 20 bytes, commonly colon-separated (length 59 when with colons)
    with_colons = random.random() < 0.8
    upper = random.random() < 0.5
    return _hex_pairs(20, with_colons, upper)


def _sha256_fp() -> str:
    # 32 bytes, commonly colon-separated (length 95 when with colons)
    with_colons = random.random() < 0.8
    upper = random.random() < 0.5
    return _hex_pairs(32, with_colons, upper)


def _short_fp() -> str:
    # Minimal small fingerprints the stubs accept (e.g., "00"),
    # or very short sequences to exercise edge cases.
    choices = ["00", "0A", "ab", "AA:BB", "01:23:45"]
    return random.choice(choices)


def _mixed_case_fp(n_bytes: int) -> str:
    # Produce hex without colons and then randomly change case per char
    s = _hex_pairs(n_bytes, with_colons=False, upper=True)
    out = []
    for ch in s:
        if ch in string.hexdigits:
            if random.random() < 0.5:
                out.append(ch.lower())
            else:
                out.append(ch.upper())
        else:
            out.append(ch)
    # Optionally insert colons at every 2 bytes to vary formatting slightly
    if random.random() < 0.4:
        # Insert colons every 2 bytes (4 hex chars)
        grouped = ["".join(out[i:i+2]) for i in range(0, len(out), 2)]
        return ":".join(grouped)
    return "".join(out)


def _fingerprint_variants() -> list[str]:
    # Build a pool of plausible fingerprints
    fps = []
    fps.append(_sha256_fp())
    fps.append(_sha1_fp())
    fps.append(_short_fp())
    # Add a couple more variants
    fps.append(_mixed_case_fp(32))
    fps.append(_mixed_case_fp(20))
    return fps


def _build_input_blob(fps: list[str]) -> bytes:
    # The fuzz stubs use FUZZ_PARAM_STR multiple times to fetch inputs.
    # We'll concatenate multiple newline-separated candidates so each call
    # can read a different slice depending on harness behavior, while still
    # being valid standalone strings if taken whole.
    # Keep under 4096 bytes.
    body = "\n".join(fps)
    if len(body) > 4000:
        body = body[:4000]
    return body.encode("ascii", errors="ignore")


def generate(seed: int) -> bytes:
    random.seed(seed)
    # Create a diverse set of fingerprints to exercise:
    # - CIRCNetwork::AddTrustedFingerprint (expects hex pairs, accepts variations)
    # - CIRCNetwork::DelTrustedFingerprint (may try existing; else uses provided string)
    # - CZNCSock::SetSSLTrustedPeerFingerprints (accepts a set of strings)
    fps = []

    # Ensure at least one canonical SHA-256 and one SHA-1
    fps.append(_sha256_fp())
    fps.append(_sha1_fp())

    # Add several more diverse entries
    for _ in range(6):
        fps.extend(_fingerprint_variants())

    # Deduplicate while preserving order
    seen = set()
    unique_fps = []
    for fp in fps:
        if fp not in seen:
            seen.add(fp)
            unique_fps.append(fp)

    # Shuffle to vary ordering per seed
    random.shuffle(unique_fps)

    # Limit count to keep size bounded
    unique_fps = unique_fps[:50]

    return _build_input_blob(unique_fps)

import random
import string
from typing import List

# Target: Generate valid HTTP header names and values for CWebSock::AddHeader fuzz stub.
# Constraints:
# - Two FUZZ_PARAM_STR() calls are used: header name and header value.
# - Stub strips CR/LF; empty name is replaced with "X-Fuzz". We want interesting but valid names.
# - No I/O; return a single bytes buffer <= 4096 bytes.
# - The fuzzing framework will split this buffer for FUZZ_PARAM_STR calls in order.
# Assumption: FUZZ_PARAM_STR reads a length-prefixed or delimiter-separated chunk. Since the exact
# mechanism is unknown, we provide a simple concatenation with a clear separator that typically
# many harnesses understand (e.g., newline-separated). If the framework uses a custom format,
# these remain plain bytes without CR/LF inside names as the stub strips them anyway.
# We'll produce: name\nvalue (single LF between them), and avoid CR in both. Values may contain spaces and ASCII but no CR/LF.

# Helper lists of interesting standard and custom header names
STANDARD_HEADERS = [
    "Content-Type", "Content-Length", "User-Agent", "Accept", "Accept-Encoding",
    "Accept-Language", "Host", "Authorization", "Cache-Control", "Pragma",
    "Connection", "Upgrade", "Origin", "Referer", "If-None-Match", "If-Modified-Since",
    "Cookie", "Set-Cookie", "Range", "ETag", "X-Forwarded-For", "X-Real-IP",
    "Transfer-Encoding", "TE", "Via", "DNT", "Sec-Fetch-Mode", "Sec-Fetch-Site",
    "Sec-WebSocket-Key", "Sec-WebSocket-Version", "Sec-WebSocket-Protocol"
]

# Interesting custom prefixes
CUSTOM_PREFIXES = ["X-", "X-ZNC-", "X-Test-", "X-Fuzz-", "X-Request-", "X-Trace-", "X-Feature-"]

# Valid token characters per RFC 7230 tchar (excluding control chars and separators)
# tchar = "!#$%&'*+-.^_`|~" DIGIT ALPHA
TCHARS = "!#$%&'*+-.^_`|~" + string.ascii_letters + string.digits

# Generate a valid header name
def gen_header_name(rng: random.Random) -> str:
    # Choose strategy
    choice = rng.random()
    if choice < 0.4:
        name = rng.choice(STANDARD_HEADERS)
    elif choice < 0.7:
        # Custom prefix + token
        prefix = rng.choice(CUSTOM_PREFIXES)
        core_len = rng.randint(3, 16)
        core = ''.join(rng.choice(TCHARS) for _ in range(core_len))
        # Ensure token does not end with '-'
        core = core.strip('-') or 'Token'
        name = prefix + core
    else:
        # Fully random token with possible dashes separating parts
        parts = []
        n_parts = rng.randint(1, 3)
        for _ in range(n_parts):
            plen = rng.randint(2, 10)
            part = ''.join(rng.choice(TCHARS) for _ in range(plen)).strip('-') or 'H'
            parts.append(part)
        name = '-'.join(parts)
    # Normalize: header names commonly case-insensitive; mix cases
    patterns = [str.lower, str.upper, str.title]
    name = rng.choice(patterns)(name)
    # Ensure no CR/LF
    name = name.replace('\r', '').replace('\n', '')
    if not name:
        name = 'X-Fuzz'
    return name[:256]

# Generate a plausible header value (no CR/LF)
def gen_header_value(rng: random.Random, name: str) -> str:
    lname = name.lower()
    # Specialized values for known headers
    if 'content-type' in lname:
        types = [
            'text/plain; charset=utf-8',
            'text/html; charset=utf-8',
            'application/json',
            'application/octet-stream',
            'application/x-www-form-urlencoded'
        ]
        return rng.choice(types)
    if 'accept-encoding' in lname:
        return rng.choice(['gzip, deflate, br', 'gzip', 'br', 'identity'])
    if 'accept-language' in lname:
        return rng.choice(['en-US,en;q=0.9', 'en', 'de-DE,de;q=0.8', 'fr-FR,fr;q=0.8'])
    if lname == 'host':
        hosts = ['example.com', 'localhost', 'znc.local', 'test.invalid']
        port = rng.choice(['', ':80', ':443', f":{rng.randint(1024, 65535)}"]) 
        return rng.choice(hosts) + port
    if 'authorization' in lname:
        # Basic or Bearer
        if rng.random() < 0.5:
            # Simple base64-ish placeholder without CRLF
            creds = 'dXNlcjpwYXNz'  # user:pass
            return 'Basic ' + creds
        else:
            tok = ''.join(rng.choice(string.ascii_letters + string.digits) for _ in range(24))
            return 'Bearer ' + tok
    if 'user-agent' in lname:
        uas = [
            'curl/7.88.1',
            'Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 Chrome/120.0 Safari/537.36',
            'Python-urllib/3.10',
            'ZNC-Fuzzer/1.0'
        ]
        return rng.choice(uas)
    if 'connection' in lname:
        return rng.choice(['keep-alive', 'close', 'upgrade'])
    if 'upgrade' in lname:
        return rng.choice(['websocket', 'h2c'])
    if 'etag' in lname:
        tag = '"' + ''.join(rng.choice(string.hexdigits.lower()) for _ in range(8)) + '"'
        return tag
    if 'cookie' in lname:
        # Simple cookie string without semicolons that cause splits in some parsers is fine
        kvs = []
        for _ in range(rng.randint(1, 3)):
            k = 'k' + ''.join(rng.choice(string.ascii_lowercase) for _ in range(rng.randint(3,6)))
            v = ''.join(rng.choice(string.ascii_letters + string.digits) for _ in range(rng.randint(4,10)))
            kvs.append(f"{k}={v}")
        return '; '.join(kvs)
    if 'x-forwarded-for' in lname or 'x-real-ip' in lname:
        # IPv4 or IPv6 literal without brackets
        if rng.random() < 0.7:
            return '.'.join(str(rng.randint(0, 255)) for _ in range(4))
        else:
            # Simplified IPv6
            return ':'.join('%.x' % rng.randint(0, 65535) for _ in range(8))
    if 'range' in lname:
        start = rng.randint(0, 500)
        end = start + rng.randint(0, 500)
        return f"bytes={start}-{end}"
    if 'cache-control' in lname:
        return rng.choice(['no-cache', 'no-store', 'max-age=0', 'max-age=3600, public'])

    # Generic value: mix of safe visible ASCII excluding CR/LF
    safe = string.ascii_letters + string.digits + " -_./;:=,+()[]{}@#$%^&*'\""
    length = rng.randint(0, 64)
    val = ''.join(rng.choice(safe) for _ in range(length)).strip()
    # Avoid empty too often; sometimes empty is interesting
    if val == '' and rng.random() < 0.7:
        val = '1'
    return val.replace('\r', '').replace('\n', '')[:512]


def build_two_lines(name: str, value: str) -> bytes:
    # Compose as name\nvalue with LF separator, no CRs inside
    name = name.replace('\r', '').replace('\n', '')
    value = value.replace('\r', '').replace('\n', '')
    blob = name + '\n' + value
    return blob.encode('utf-8')


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # Choose a scenario to exercise different code paths
    scenario = rng.randint(0, 7)

    if scenario == 0:
        # Standard header with common value
        name = gen_header_name(rng)
        value = gen_header_value(rng, name)
        return build_two_lines(name, value)
    elif scenario == 1:
        # Empty value
        name = gen_header_name(rng)
        value = ''
        return build_two_lines(name, value)
    elif scenario == 2:
        # Long custom header name and value
        name = (rng.choice(CUSTOM_PREFIXES) + ''.join(rng.choice(TCHARS) for _ in range(24))).strip('-')
        value = ''.join(rng.choice(string.ascii_letters + string.digits + '-._;:/+ ') for _ in range(200)).strip()
        return build_two_lines(name, value)
    elif scenario == 3:
        # Name that would be replaced if empty; instead provide minimal valid
        name = 'X-Fuzz'
        value = gen_header_value(rng, name)
        return build_two_lines(name, value)
    elif scenario == 4:
        # Specialized known headers to trigger specific branches
        name = rng.choice(["Content-Type", "Authorization", "User-Agent", "Host", "Cookie"]) 
        value = gen_header_value(rng, name)
        return build_two_lines(name, value)
    elif scenario == 5:
        # Mixed case and unusual token characters
        prefix = rng.choice(CUSTOM_PREFIXES)
        core = ''.join(rng.choice("!$%&'*+^_`|~" + string.ascii_letters + string.digits) for _ in range(rng.randint(5,12)))
        name = (prefix + core).title()
        value = gen_header_value(rng, name)
        return build_two_lines(name, value)
    elif scenario == 6:
        # Value with quotes and commas
        name = gen_header_name(rng)
        value = 'token="%s", q=%s' % (
            ''.join(rng.choice(string.ascii_letters + string.digits) for _ in range(10)),
            rng.choice(['1', '0.7', '0'])
        )
        return build_two_lines(name, value)
    else:
        # Short random token name, short value
        parts = [''.join(rng.choice(TCHARS) for _ in range(rng.randint(2,6))).strip('-') or 'H']
        if rng.random() < 0.5:
            parts.append(''.join(rng.choice(TCHARS) for _ in range(rng.randint(2,6))).strip('-') or 'V')
        name = '-'.join(parts)
        value = ''.join(rng.choice(string.ascii_letters + string.digits) for _ in range(rng.randint(1,16)))
        return build_two_lines(name, value)
